def _build_implicit_queryset(self, model, requirements):
        """Build a queryset based on implicit requirements."""
        queryset = model.objects.all()
        if requirements.get('exclude_deleted'):
            queryset = queryset.filter(deleted=False)
        if requirements.get('exclude_unpublished'):
            queryset = queryset.filter(published=True)
        if requirements.get('exclude_future'):
            queryset = queryset.filter(published_at__lte=timezone.now())
        return queryset

